import { useState, useContext } from 'react';
import { useNavigate } from 'react-router-dom';
import AuthContext from '../context/AuthContext';
import axios from 'axios';
import 'bootstrap/dist/css/bootstrap.min.css';
import '@fortawesome/fontawesome-free/css/all.min.css';

export default function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('student');
  const { login } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post('http://localhost:5000/api/auth/login', {
        email,
        password,
        role,
      });

      login(res.data);

      if (res.data.user.role === 'admin') {
        navigate('/admin');
      } else {
        navigate('/dashboard');
      }
    } catch (err) {
      alert('Login failed: ' + (err.response?.data?.error || 'Invalid credentials'));
    }
  };

  return (
    <div
      style={{
        height: '100vh',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        fontFamily: 'Inter, sans-serif',
        background: '#0b1120',
        position: 'relative',
        overflow: 'hidden'
      }}
    >

      {/* Background Glow (PRO LEVEL DETAIL) */}
      <div style={{
        position: 'absolute',
        width: '600px',
        height: '600px',
        background: 'radial-gradient(circle, rgba(59,130,246,0.25), transparent 70%)',
        top: '-100px',
        left: '-100px'
      }} />

      <div style={{
        position: 'absolute',
        width: '500px',
        height: '500px',
        background: 'radial-gradient(circle, rgba(16,185,129,0.2), transparent 70%)',
        bottom: '-120px',
        right: '-120px'
      }} />

      {/* Main Card */}
      <div
        style={{
          width: '420px',
          padding: '45px 35px',
          borderRadius: '20px',
          background: 'rgba(17,24,39,0.85)',
          backdropFilter: 'blur(15px)',
          border: '1px solid rgba(255,255,255,0.08)',
          boxShadow: '0 25px 60px rgba(0,0,0,0.6)',
          zIndex: 2
        }}
      >

        {/* Header */}
        <div style={{ textAlign: 'center', marginBottom: '30px' }}>
          <img
            src="/logo.png"
            alt="logo"
            style={{
              width: '75px',
              borderRadius: '50%',
              marginBottom: '10px'
            }}
          />
          <h2 style={{ color: '#ffffff', fontWeight: '600', marginBottom: '5px' }}>
            Online Quiz Platform
          </h2>
          <p style={{ color: '#9ca3af', fontSize: '14px' }}>
            Sign in to continue
          </p>
        </div>

        <form onSubmit={handleSubmit}>

          {/* Email */}
          <div style={{ marginBottom: '20px' }}>
            <label style={{ color: '#9ca3af', fontSize: '13px' }}>Email</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              style={{
                width: '100%',
                padding: '12px',
                marginTop: '6px',
                borderRadius: '10px',
                border: '1px solid #374151',
                background: '#020617',
                color: 'white',
                outline: 'none',
                transition: '0.2s'
              }}
            />
          </div>

          {/* Password */}
          <div style={{ marginBottom: '20px' }}>
            <label style={{ color: '#9ca3af', fontSize: '13px' }}>Password</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              style={{
                width: '100%',
                padding: '12px',
                marginTop: '6px',
                borderRadius: '10px',
                border: '1px solid #374151',
                background: '#020617',
                color: 'white',
                outline: 'none'
              }}
            />
          </div>

          {/* Role */}
          <div style={{ marginBottom: '25px' }}>
            <label style={{ color: '#9ca3af', fontSize: '13px' }}>Role</label>

            <div style={{
              display: 'flex',
              marginTop: '8px',
              borderRadius: '10px',
              background: '#020617',
              padding: '5px'
            }}>
              <button
                type="button"
                onClick={() => setRole('student')}
                style={{
                  flex: 1,
                  padding: '10px',
                  borderRadius: '8px',
                  border: 'none',
                  background: role === 'student' ? '#22c55e' : 'transparent',
                  color: role === 'student' ? '#000' : '#9ca3af',
                  fontWeight: '500'
                }}
              >
                Student
              </button>

              <button
                type="button"
                onClick={() => setRole('admin')}
                style={{
                  flex: 1,
                  padding: '10px',
                  borderRadius: '8px',
                  border: 'none',
                  background: role === 'admin' ? '#3b82f6' : 'transparent',
                  color: role === 'admin' ? '#fff' : '#9ca3af',
                  fontWeight: '500'
                }}
              >
                Admin
              </button>
            </div>
          </div>

          {/* Button */}
          <button
            type="submit"
            style={{
              width: '100%',
              padding: '13px',
              borderRadius: '12px',
              border: 'none',
              background: 'linear-gradient(90deg, #3b82f6, #06b6d4)',
              color: 'white',
              fontWeight: '600',
              fontSize: '15px',
              letterSpacing: '0.5px',
              transition: '0.3s'
            }}
          >
            Login →
          </button>

        </form>

        {/* Footer */}
        <div style={{ textAlign: 'center', marginTop: '20px' }}>
          <span style={{ color: '#9ca3af', fontSize: '13px' }}>
            Don’t have an account?{' '}
            <a href="/register" style={{ color: '#22c55e' }}>
              Sign Up
            </a>
          </span>
        </div>

      </div>
    </div>
  );
}
